// Copyright 2026 ReC Sandbox. Distributed under the terms in LICENSE.md at the repository root.#pragma once// The CineCam Grade panel (S10 item 5): the three Primaries wheels and every other grade control// of the selected entity's CineCam Grade, in one window - Tools -> Cinematic Camera ->// CineCam Grade.//// It is a VIEW of the component and never a second copy of it: every editor idle it re-reads the// values and repaints if they moved, so an edit in the entity inspector, an undo, a preset apply// and (later) a TrackView scrub all show up here without this panel knowing they happened. It// only owns the values while the user is actually dragging something in it.//// Binding, and the rule the user set: exactly one selected entity that has a CineCam Grade ->// editable, the header names it. Anything else -> read-only and greyed, header says why, the last// numbers stay on screen.#include <EditorFramework/Editor.h>#include <IEditor.h>#include "CineGradeBinding.h"#include <memory>class QCheckBox;class QComboBox;class QDoubleSpinBox;class QGridLayout;class QLabel;class QLineEdit;namespace CineCamGrade{class CCineWheelControl;class CCineFloatRow;class CCineGradePanel : public CDockableEditor, public IEditorNotifyListener{	Q_OBJECTpublic:	explicit CCineGradePanel(QWidget* pParent = nullptr);	virtual ~CCineGradePanel();	// CDockableEditor	virtual const char* GetEditorName() const override { return "CineCam Grade"; }	// ~CDockableEditor	// IEditorNotifyListener	virtual void OnEditorNotifyEvent(EEditorNotifyEvent event) override;	// ~IEditorNotifyListenerprotected:	//! One breakpoint: three wheels in a row in a wide dock, stacked in a narrow one.	virtual void resizeEvent(QResizeEvent* pEvent) override;private:	QWidget* BuildWheels();	QWidget* BuildTone();	QWidget* BuildCurves();	QWidget* BuildCdlBase();	QWidget* BuildLook();	//! Put the three wheels in one row or in one column. Layout only - the controls are the same	//! objects either way, so a reflow in the middle of a drag would still be harmless.	void ApplyWheelLayout(bool bStacked);	//! Hook one control's three signals into the one transaction the panel keeps.	template<typename TControl> void Wire(TControl* pControl);	void Rebind(bool bForce);	void Poll();	void SetBoundState(const char* szReason);	//! One undo step per gesture: opened on the first change of a drag, closed on the release.	void BeginInteraction();	void PushValues();	void EndInteraction();	//! Widgets -> m_values (called at the start of every push) and m_values -> widgets.	void CollectFromWidgets();	void RefreshWidgets();	void OnBrowseLmt();	std::unique_ptr<CEntityGradeTarget> m_pTarget;	SGradeValues                        m_values;	CCineWheelControl* m_pLift = nullptr;	CCineWheelControl* m_pGamma = nullptr;	CCineWheelControl* m_pGain = nullptr;	CCineFloatRow*  m_pContrast = nullptr;	CCineFloatRow*  m_pPivot = nullptr;	CCineFloatRow*  m_pSaturation = nullptr;	CCineFloatRow*  m_pMasterCurve[kKnotCount] = { nullptr };	CCineFloatRow*  m_pSatCurve[kKnotCount] = { nullptr };	//! Slope / Offset / Power, three channels each.	QDoubleSpinBox* m_pCdl[3][3] = { { nullptr } };	QCheckBox* m_pBypass = nullptr;	QLabel*    m_pHeader = nullptr;	QLineEdit* m_pLmtFile = nullptr;	QComboBox* m_pLmtSpace = nullptr;	QLineEdit* m_pPreset = nullptr;	QWidget*   m_pControls = nullptr;	QGridLayout* m_pWheelLayout = nullptr;	bool         m_wheelsStacked = false;	bool m_interacting = false;	bool m_changedInInteraction = false;	bool m_updatingWidgets = false;	int  m_rebindCountdown = 0;};} // namespace CineCamGrade